 "content": "def transform(grid):
    """Overlay the four stacked 3x6 color layers in order, keeping the first
    nonzero cell in each position (upper layers take priority).
    """
    if len(grid) % 4:
        raise ValueError("expected four equally sized stacked layers")
    h = len(grid) // 4
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]
    for layer in range(4):
        for r in range(h):
            for c in range(w):
                value = grid[layer * h + r][c]
                if out[r][c] == 0 and value != 0:
                    out[r][c] = value
    return out
