 "content": "def transform(grid):
    """Composite the four 3x6 color layers using priority 5 > 4 > 8 > 2."""
    h = len(grid) // 4
    w = len(grid[0])
    # Input bands are ordered 5, 4, 2, 8; visibility priority differs for
    # the bottom two bands, with color 8 in front of color 2.
    out = [[0] * w for _ in range(h)]
    for layer in (0, 1, 3, 2):
        for r in range(h):
            for c in range(w):
                v = grid[layer * h + r][c]
                if out[r][c] == 0 and v:
                    out[r][c] = v
